window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-67891ea2de4d65cf"]={"versions": [{"id": "FIG-67891ea2de4d65cf", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Aktivitätsdiagramm (Activity Diagram), Teilschritt-Spezifikation einer Opaque Action mit Kontrollfluss (Initial Node, Action Node, Activity Final Node, UML-Kommentar).\n</li><li><strong>Funktionale Einordnung:</strong> AUTOSAR Foundation / Classic &amp; Adaptive Platform (<code>AUTOSAR_FO_PRS_E2EProtocol</code>, R24-11). Das Diagramm spezifiziert die atomare Logik des Teilschritts „Increment Counter“ innerhalb der Schutzfunktion <code>E2E_P76Protect()</code> des E2E-Profils 76 (PRS_E2E_01403, PRS_E2E_01404, abgeleitet aus RS_E2E_08539).\n</li><li><strong>Zweck:</strong> Sicherstellung der Erkennung von Datenverlust, Wiederholungsfehlern und Sequenzfehlern auf Empfängerseite durch zyklische Aktualisierung des Alive-/Sequence-Counters vor der Serialisierung/Übertragung.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aktivitäts-Kontext:</strong>\n<ul class=\"fig-list\"><li><code>E2E_P76Protect()</code>: Umschließende API-Funktion / Aktivität (symbolisiert durch das Icon für Sub-Aktivitätszerlegung oben links).\n</li></ul>\n</li><li><strong>Zustandsstruktur &amp; Datenobjekte:</strong>\n<ul class=\"fig-list\"><li><code>State</code>: Zeiger auf die zustandsbehaftete Sender-Struktur <code>E2E_P76ProtectStateType</code>.\n</li><li><code>State-&gt;Counter</code>: 5-Bit-Zählervariable (<code>uint8</code>-basierter Skalar), definiert im Wertebereich <code>[0x00 .. 0x1F]</code>.\n</li></ul>\n</li><li><strong>Modell-Elemente:</strong>\n<ul class=\"fig-list\"><li><em>Initial Node</em> (schwarzer Vollkreis): Einstiegspunkt des Inkrementierungs-Teilschritts.\n</li><li><em>Action Node</em> (<code>State-&gt;Counter++</code>): Zustandstransformation des Zählers.\n</li><li><em>Activity Final Node</em> (Bullauge / Doppelkreis): Terminierung des Einzelschritts.\n</li><li><em>UML Comment / Note</em>: Normative Randeinschränkung für den Überlauf (<code>After Counter has reached its maximum 0x1F, the next Counter value is 0</code>).\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Ausführungsmodell:</strong> Synchroner, rein sequentieller Kontrollfluss ohne Verzweigung oder Parallelisierung innerhalb der E2E-Sende-Pipeline:\n<ol class=\"fig-list\"><li><strong>Trigger:</strong> Erreichen der Sequenzposition zur Zähleraktualisierung innerhalb von <code>E2E_P76Protect()</code> (nach Initialvalidierung der Eingangsparameter).\n</li><li><strong>Zustandsübergang:</strong> Inkrementierung des Zählers mit Modulo-32-Arithmetik:\n $$\\text{Counter}_{k+1} = (\\text{Counter}_k + 1) \\pmod{32}$$\n bzw. bei Erreichen von <code>0x1F</code> (31 dezimal) Rücksprung auf <code>0x00</code>.\n</li><li><strong>Abschluss:</strong> Direkter Übergang zum <em>Activity Final Node</em>; Rückgabe des Kontrollflusses an die Folgeschritte von <code>E2E_P76Protect()</code> (z. B. Einfügen in den PDU-Buffer und CRC-Berechnung).\n</li></ol>\n</li><li><strong>Fehlerpfade/Callbacks:</strong> Keine asynchronen Events, keine Det-/Dem-Meldungen und keine Fehlerausstiege in diesem isolierten Teilschritt.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Bitbreite &amp; Maskierung (C-Implementierung):</strong>\n<ul class=\"fig-list\"><li>Da Standard-C-Typen (<code>uint8</code>) bei <code>0xFF</code> überlaufen, erfordert E2E Profile 76 eine explizite 5-Bit-Begrenzung im Treibercode:\n<pre class=\"fig-pre\"><code>State-&gt;Counter = (State-&gt;Counter + 1u) &amp; 0x1FU;</code></pre>\n</li></ul>\n</li><li><strong>Reentrancy &amp; Speicherverwaltung:</strong>\n<ul class=\"fig-list\"><li><code>State</code> muss im nicht-flüchtigen/statischen RAM der sendenden Entität (SW-C bzw. E2E-PduM / Com-Stack) persistiert werden.\n</li><li><code>E2E_P76Protect()</code> ist bezogen auf denselben <code>State</code> nicht reentrant. Greifen mehrere Tasks oder Preemption-Ebenen auf dieselbe Daten-ID zu, müssen Aufrufe auf Applikations-/Middleware-Ebene gemutext werden.\n</li></ul>\n</li><li><strong>API-Vertragsbindung:</strong>\n<ul class=\"fig-list\"><li>Der Zähler darf nur inkrementiert werden, wenn die Eingangsparameter gültig sind (<code>E2E_E_OK</code>). Bei Parametrierfehlern (<code>E2E_E_INPUTERR_NULL</code>, ungültige Längen) verbleibt <code>State-&gt;Counter</code> unverändert.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-0891964b7890d927", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Aktivitätsdiagramm (Activity Diagram), Teilschritt-Spezifikation einer Opaque Action mit Kontrollfluss (Initial Node, Action Node, Activity Final Node, UML-Kommentar).\n</li><li><strong>Funktionale Einordnung:</strong> AUTOSAR Foundation / Classic &amp; Adaptive Platform (<code>AUTOSAR_FO_PRS_E2EProtocol</code>, R24-11). Das Diagramm spezifiziert die atomare Logik des Teilschritts „Increment Counter“ innerhalb der Schutzfunktion <code>E2E_P76Protect()</code> des E2E-Profils 76 (PRS_E2E_01403, PRS_E2E_01404, abgeleitet aus RS_E2E_08539).\n</li><li><strong>Zweck:</strong> Sicherstellung der Erkennung von Datenverlust, Wiederholungsfehlern und Sequenzfehlern auf Empfängerseite durch zyklische Aktualisierung des Alive-/Sequence-Counters vor der Serialisierung/Übertragung.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aktivitäts-Kontext:</strong>\n<ul class=\"fig-list\"><li><code>E2E_P76Protect()</code>: Umschließende API-Funktion / Aktivität (symbolisiert durch das Icon für Sub-Aktivitätszerlegung oben links).\n</li></ul>\n</li><li><strong>Zustandsstruktur &amp; Datenobjekte:</strong>\n<ul class=\"fig-list\"><li><code>State</code>: Zeiger auf die zustandsbehaftete Sender-Struktur <code>E2E_P76ProtectStateType</code>.\n</li><li><code>State-&gt;Counter</code>: 5-Bit-Zählervariable (<code>uint8</code>-basierter Skalar), definiert im Wertebereich <code>[0x00 .. 0x1F]</code>.\n</li></ul>\n</li><li><strong>Modell-Elemente:</strong>\n<ul class=\"fig-list\"><li><em>Initial Node</em> (schwarzer Vollkreis): Einstiegspunkt des Inkrementierungs-Teilschritts.\n</li><li><em>Action Node</em> (<code>State-&gt;Counter++</code>): Zustandstransformation des Zählers.\n</li><li><em>Activity Final Node</em> (Bullauge / Doppelkreis): Terminierung des Einzelschritts.\n</li><li><em>UML Comment / Note</em>: Normative Randeinschränkung für den Überlauf (<code>After Counter has reached its maximum 0x1F, the next Counter value is 0</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Ausführungsmodell:</strong> Synchroner, rein sequentieller Kontrollfluss ohne Verzweigung oder Parallelisierung innerhalb der E2E-Sende-Pipeline:\n<ol class=\"fig-list\"><li><strong>Trigger:</strong> Erreichen der Sequenzposition zur Zähleraktualisierung innerhalb von <code>E2E_P76Protect()</code> (nach Initialvalidierung der Eingangsparameter).\n</li><li><strong>Zustandsübergang:</strong> Inkrementierung des Zählers mit Modulo-32-Arithmetik:\n $$\\text{Counter}_{k+1} = (\\text{Counter}_k + 1) \\pmod{32}$$\n bzw. bei Erreichen von <code>0x1F</code> (31 dezimal) Rücksprung auf <code>0x00</code>.\n</li><li><strong>Abschluss:</strong> Direkter Übergang zum <em>Activity Final Node</em>; Rückgabe des Kontrollflusses an die Folgeschritte von <code>E2E_P76Protect()</code> (z. B. Einfügen in den PDU-Buffer und CRC-Berechnung).\n</li></ol>\n</li><li><strong>Fehlerpfade/Callbacks:</strong> Keine asynchronen Events, keine Det-/Dem-Meldungen und keine Fehlerausstiege in diesem isolierten Teilschritt.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Bitbreite &amp; Maskierung (C-Implementierung):</strong>\n<ul class=\"fig-list\"><li>Da Standard-C-Typen (<code>uint8</code>) bei <code>0xFF</code> überlaufen, erfordert E2E Profile 76 eine explizite 5-Bit-Begrenzung im Treibercode:\n<pre class=\"fig-pre\"><code>State-&gt;Counter = (State-&gt;Counter + 1u) &amp; 0x1FU;</code></pre>\n</li></ul>\n</li><li><strong>Reentrancy &amp; Speicherverwaltung:</strong>\n<ul class=\"fig-list\"><li><code>State</code> muss im nicht-flüchtigen/statischen RAM der sendenden Entität (SW-C bzw. E2E-PduM / Com-Stack) persistiert werden.\n</li><li><code>E2E_P76Protect()</code> ist bezogen auf denselben <code>State</code> nicht reentrant. Greifen mehrere Tasks oder Preemption-Ebenen auf dieselbe Daten-ID zu, müssen Aufrufe auf Applikations-/Middleware-Ebene gemutext werden.\n</li></ul>\n</li><li><strong>API-Vertragsbindung:</strong>\n<ul class=\"fig-list\"><li>Der Zähler darf nur inkrementiert werden, wenn die Eingangsparameter gültig sind (<code>E2E_E_OK</code>). Bei Parametrierfehlern (<code>E2E_E_INPUTERR_NULL</code>, ungültige Längen) verbleibt <code>State-&gt;Counter</code> unverändert.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-67891ea2de4d65cf", "to": "FIG-0891964b7890d927", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
